mapper.select:
select t.id, t.biz_type, t.currency, t.amount, t.status, t.account_info, t.pay_method,
       t.pay_proof_url, t.pay_mode, t.create_time, t.audit_time, t.audit_remark, t.remark
from (

    select r.recharge_id as id, 'RECHARGE' as biz_type, r.currency, r.amount, r.status,
           null as account_info, null as pay_method, null as pay_proof_url, r.pay_mode,
           r.create_time, r.audit_time, r.audit_remark, r.remark
    from biz_recharge r
    where r.member_id = #{memberId}
    and r.currency = #{currency}
    and r.status = #{status}


    union all


    select w.withdraw_id as id, 'WITHDRAW' as biz_type, w.currency, w.amount, w.status,
           w.account_info, w.pay_method, w.pay_proof_url, null as pay_mode,
           w.create_time, w.audit_time, w.audit_remark, w.remark
    from biz_withdraw w
    where w.member_id = #{memberId}
    and w.currency = #{currency}
    and w.status = #{status}

) t
order by t.create_time desc, t.id desc
